parameters.jsCode:
// The same instruction the Telegram bot uses, so a summary reads the same
// whichever way the article arrived. Improving it is Mikko's part.
return { json: {
  task: 'summarise',
  item_id: $json.id,
  system_prompt: 'Tiivistä seuraava uutinen jäsenkirjeeseen kolmella lyhyellä suomenkielisellä lauseella. Kerro vain se mitä tekstissä lukee. Älä keksi mitään lisää.',
  user_text: `${$json.title}\n\n${$json.raw_text}`,
} };

// A link an editor sent to the bot while the AI was down gets its summary
// here, and the bot promised to send it. Anything else just carries on.
// A failed message never stops the loop: the summary is saved either way.
const r = $json;
if (r.status === 'summarised' && r.telegram_user_id) {
  const text = ($('Summarise').first().json.text || '').trim();
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,
      body: { chat_id: r.telegram_user_id, text: `Summary for: ${r.title}\n\n${text}`,
              disable_web_page_preview: true },
      json: true,
    });
  } catch (e) { /* nothing more to do */ }
}
return [{ json: r }];

// Ask the model server whether it is there before sending it up to 20
// articles. If it is down, stop here: the articles stay queued and the next
// run, 15 minutes later, tries again. Nothing is marked failed for an outage
// that was not the article's fault.
const rows = $input.all();
const cfg = rows[0].json;
if (cfg.llm_provider === 'ollama') {
  try {
    await this.helpers.httpRequest({ url: `${cfg.llm_base_url}/api/version`, timeout: 5000, json: true });
  } catch (e) {
    return [];
  }
}
return rows;
